// Library DERIVATIVES: deterministic recipes (no model calls), generated lazily on first request and cached as
// content-addressed objects. A recipe id carries its version (`thumb@1`); changing a recipe's output = a new
// version, so cached objects are never silently different. Every recipe has an output cap.
//   thumb@1        PNG <= 256 px edge. PNG sources in-process (pure JS: bounded decode, box-filter downscale,
//                  nearest-neighbour upscale of tiny pixel art to >= 64 px). JPEG sources via Python PIL (pinned
//                  script, version recorded). Sources: the file itself (sprite/texture/decal PNG), a sibling
//                  `<stem>.png` (Poly Haven models), the folder's `<Name>.png` / `*_Color.jpg` / `*_TONEMAPPED.jpg`
//                  (ambientCG sets, HDRIs, decals). A bare .hdr/.exr or a .glb without a sibling image: no thumbnail
//                  (needs a tone-mapper / renderer: not built).
//   preview-ogg@1  audio preview: mono 44.1 kHz Vorbis q3, first 30 s, loudness-normalised (EBU R128 single pass),
//                  bit-exact muxing, metadata stripped (ffmpeg). The ONLY way audio ever leaves the library: the raw
//                  file is never served (and the owner's proprietary library only once it is cleared).
//   glb-opt@1      gltf-transform optimize (weld, dedup, prune, meshopt) on the original .glb.
//   bundle@1       folder kinds (PBR sets, HDRIs, decals): a deterministic zip (sorted names, fixed timestamps) of
//                  the folder's image + material files (.blend / .usdc scene files left out).
// SERVER ONLY (node:child_process for the tool recipes). HOST SEAM: no Nxeon imports.
import { spawnSync } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import os from "node:os";
import path from "node:path";
import { deflateSync } from "node:zlib";
import { decodePng } from "../png-decode";
import { crc32 } from "../../textures/png";
import { zip } from "../../textures/zip";
import type { CatalogEntry, CatalogKind } from "../v2/entry";

export const RECIPE_IDS = ["thumb@1", "preview-ogg@1", "glb-opt@1", "bundle@1"] as const;
export type RecipeId = (typeof RECIPE_IDS)[number];
export const RECIPE_MIME: Record<RecipeId, string> = { "thumb@1": "image/png", "preview-ogg@1": "audio/ogg", "glb-opt@1": "model/gltf-binary", "bundle@1": "application/zip" };
/** output caps per recipe (bytes) */
export const RECIPE_MAX_BYTES: Record<RecipeId, number> = { "thumb@1": 512 * 1024, "preview-ogg@1": 2 * 1024 * 1024, "glb-opt@1": 48 * 1024 * 1024, "bundle@1": 160 * 1024 * 1024 };
export const THUMB_EDGE = 256;
export const PREVIEW_SECONDS = 30;

const FOLDER_KINDS: readonly CatalogKind[] = ["texture-set", "hdri", "decal"];
/** a folder of files: ambientCG / Poly Haven sets, HDRIs, decals, and frame-sequence flipbooks */
export const isFolderEntry = (e: Pick<CatalogEntry, "kind" | "tech">) => (FOLDER_KINDS.includes(e.kind) && !/^(png|jpg|jpeg)$/i.test(e.tech.format)) || (e.kind === "flipbook" && /sequence/i.test(e.tech.format));
const isAudio = (k: CatalogKind) => k === "sound" || k === "music";

/** Which derivatives an entry can have (the store still answers "not_available" when a source/tool is missing). */
export function recipesFor(e: Pick<CatalogEntry, "kind" | "tech">): RecipeId[] {
  if (isAudio(e.kind)) return ["preview-ogg@1"];
  if (e.kind === "model") return /^glb$/i.test(e.tech.format) ? ["thumb@1", "glb-opt@1"] : ["thumb@1"];
  if (e.kind === "animation-clip" || e.kind === "motion-preset" || e.kind === "effect-preset") return []; // a clip lives inside its model; presets are small JSON
  if (e.kind === "animated-model") return /^glb$/i.test(e.tech.format) ? ["thumb@1", "glb-opt@1"] : [];
  return isFolderEntry(e) ? ["thumb@1", "bundle@1"] : ["thumb@1"];
}

export type ToolResult = { status: number | null; stdout: Buffer; stderr: string };
/** argv only (never a shell), stdin in, stdout out, hard timeout + output cap */
export type ToolRunner = (bin: string, args: readonly string[], input: Uint8Array | null, opts: { timeoutMs: number; maxOutput: number }) => ToolResult;
export const spawnTool: ToolRunner = (bin, args, input, opts) => {
  const r = spawnSync(bin, [...args], { input: input ?? undefined, maxBuffer: opts.maxOutput, timeout: opts.timeoutMs, killSignal: "SIGKILL", env: { PATH: "/usr/bin:/bin", LC_ALL: "C" } as unknown as NodeJS.ProcessEnv });
  return { status: r.error ? null : r.status, stdout: r.stdout ?? Buffer.alloc(0), stderr: String(r.error?.message ?? r.stderr ?? "").slice(0, 400) };
};

export type DeriveTools = { ffmpeg: string | null; python: string | null; gltfTransform: string | null; run: ToolRunner };
/** what a recipe may read: the original, the thumbnail source, the folder files (all already path-confined + capped) */
export type DeriveInput = {
  entry: CatalogEntry;
  original(): Promise<Uint8Array | null>;
  thumbSource(): Promise<{ bytes: Uint8Array; ext: "png" | "jpg" } | null>;
  folder(): Promise<{ name: string; bytes: Uint8Array }[] | null>;
};
export type DeriveResult = { ok: true; bytes: Uint8Array; tool: string } | { ok: false; code: "not_available" | "tool_missing" | "tool_failed" | "too_large" | "bad_source"; error: string };

const no = (code: Extract<DeriveResult, { ok: false }>["code"], error: string): DeriveResult => ({ ok: false, code, error });

// ---- pure-JS PNG thumbnail ------------------------------------------------------------------------------------

function pngChunk(type: string, data: Uint8Array): Buffer {
  const out = Buffer.alloc(12 + data.length);
  out.writeUInt32BE(data.length, 0); out.write(type, 4, "ascii"); Buffer.from(data).copy(out, 8);
  out.writeUInt32BE(crc32(out.subarray(4, 8 + data.length)), 8 + data.length);
  return out;
}
/** RGBA w x h -> PNG (8-bit, filter 0, deflate 9): deterministic for the same pixels. */
export function encodeRgbaPng(w: number, h: number, px: Uint8ClampedArray | Uint8Array): Buffer {
  const raw = Buffer.alloc(h * (w * 4 + 1));
  for (let y = 0; y < h; y++) Buffer.from(px.buffer, px.byteOffset + y * w * 4, w * 4).copy(raw, y * (w * 4 + 1) + 1);

