// Licence gate for the PRODUCTION catalogue import (library-prod 2026-10-14). Pure: entries + the staged
// LICENCE-LEDGER.csv rows in, a decision per entry out. Nothing here reads a file or the network.
//
// An entry is imported only when ALL hold:
//   1. tier is cc0 (spdx CC0-1.0, a recorded licence page, a source URL) or proprietary-nxeon (the owner's own
//      library; only with allowProprietary, i.e. CYRUS_SOUND_LIBRARY_CLEARED=1, and never served as files anyway);
//      cc-by / user-contributed / anything else is refused.
//   2. its (source, pack) is not a NEGATIVE ledger row (SKIPPED / EXCLUDED / REJECTED / NOT ...). A pack the
//      ledger names positively, or a source the ledger includes at least one pack of, or an own-work source
//      (nxeon-procedural) passes; a source the ledger never mentions passes only on its own recorded CC0 page.
//   3. the staged path stays inside the staging root and is not a Mojang / reference / quarantine area.
// Ledger decisions: INCLUDED*, SKIPPED, EXCLUDED*, REJECTED, NOT EVALUATED IN BULK, NOT INGESTED.
// HOST SEAM: no Nxeon imports.
import type { CatalogEntry } from "../v2/entry";

export type LedgerRow = { source: string; pack: string; decision: string };
export type GateReason =
  | "tier_not_allowed" | "proprietary_not_cleared" | "no_cc0_evidence" | "ledger_negative"
  | "path_forbidden" | "source_unknown";
export type GateDecision = { ok: true; via: "ledger-pack" | "ledger-source" | "own-work" | "entry-evidence" | "owner-cleared" } | { ok: false; reason: GateReason; detail: string };

const FORBIDDEN_PATH = /(^|\/)(_owner-mc|_quarantine|_reference|_reference-mods|_raw|_lic|tmp|tmp-motion|tmp-refmods)(\/|$)/;
const OWN_WORK = new Set(["nxeon-procedural"]);
const OWNER_SOURCE = "nxeon-proprietary";
const positive = (d: string) => /^INCLUDED/i.test(d.trim());

/** Minimal RFC-4180 CSV (quoted fields, doubled quotes, newlines inside quotes). */
export function parseLedgerCsv(text: string): LedgerRow[] {
  const rows: string[][] = [];
  let cur: string[] = [], f = "", q = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (q) { if (c === '"') { if (text[i + 1] === '"') { f += '"'; i++; } else q = false; } else f += c; }
    else if (c === '"') q = true;
    else if (c === ",") { cur.push(f); f = ""; }
    else if (c === "\n") { cur.push(f); f = ""; rows.push(cur); cur = []; }
    else if (c !== "\r") f += c;
  }
  if (f || cur.length) { cur.push(f); rows.push(cur); }
  const head = rows.shift() ?? [];
  const ix = (n: string) => head.indexOf(n);
  const [s, p, d] = [ix("source"), ix("pack"), ix("decision")];
  if (s < 0 || p < 0 || d < 0) throw new Error("ledger CSV needs source, pack and decision columns");
  return rows.filter((r) => r[s]).map((r) => ({ source: r[s].trim(), pack: (r[p] ?? "").trim(), decision: (r[d] ?? "").trim() }));
}

export function createLicenceGate(ledger: readonly LedgerRow[], o: { allowProprietary: boolean }) {
  const pos = new Set<string>(), neg = new Map<string, string>(), srcPos = new Set<string>(), srcNeg = new Map<string, string>();
  const key = (s: string, p: string) => `${s}\u0000${p}`;
  for (const r of ledger) {
    if (positive(r.decision)) { pos.add(key(r.source, r.pack)); srcPos.add(r.source); }
    else if (r.pack === "-" || r.pack === "") srcNeg.set(r.source, r.decision); // whole-source rejection
    else neg.set(key(r.source, r.pack), r.decision);
  }
  return function gate(e: CatalogEntry): GateDecision {
    const p = e.provenance.path ?? "";
    if (p && (FORBIDDEN_PATH.test(p) || p.startsWith("/") || p.split("/").includes(".."))) return { ok: false, reason: "path_forbidden", detail: p.slice(0, 120) };
    const src = e.provenance.source, pack = e.provenance.pack ?? "";
    if (e.licence.tier === "proprietary-nxeon") {
      if (src !== OWNER_SOURCE) return { ok: false, reason: "tier_not_allowed", detail: `proprietary-nxeon from ${src}` };
      return o.allowProprietary ? { ok: true, via: "owner-cleared" } : { ok: false, reason: "proprietary_not_cleared", detail: "CYRUS_SOUND_LIBRARY_CLEARED is not 1" };
    }
    if (e.licence.tier !== "cc0") return { ok: false, reason: "tier_not_allowed", detail: e.licence.tier };
    if (e.licence.spdx !== "CC0-1.0" || !e.licence.sourceUrl || !/^recorded/i.test(e.licence.status ?? "")) return { ok: false, reason: "no_cc0_evidence", detail: `${e.licence.spdx ?? "-"} / ${(e.licence.status ?? "").slice(0, 40)}` };
    const n = neg.get(key(src, pack));
    if (n) return { ok: false, reason: "ledger_negative", detail: `${src}/${pack}: ${n}` };
    if (pos.has(key(src, pack))) return { ok: true, via: "ledger-pack" };
    if (OWN_WORK.has(src)) return { ok: true, via: "own-work" };
    if (srcPos.has(src)) return { ok: true, via: "ledger-source" };
    if (srcNeg.has(src)) return { ok: false, reason: "ledger_negative", detail: `${src}: ${srcNeg.get(src)}` };
    return { ok: true, via: "entry-evidence" }; // not in the ledger at all, but the entry carries its own recorded CC0 page
  };
}
