  const name = dbNameOf(url);
  if (!name) die(2, "DATABASE_URL is missing or unparsable");
  if (one("--confirm-database") !== name) die(2, `--confirm-database must be the database name in DATABASE_URL (${name})`);
  if (THROWAWAY.test(url) && !has("--allow-throwaway")) die(2, "this is a throwaway database; pass --allow-throwaway to rehearse");
  const allowProprietary = has("--allow-proprietary") || process.env.CYRUS_SOUND_LIBRARY_CLEARED === "1";
  const gate = createLicenceGate(ledgers.flatMap((f) => parseLedgerCsv(readFileSync(f, "utf8"))), { allowProprietary });

