    const missing = REQUIRED_TABLES.filter((t) => !have.has(t));
    const idx = new Set((await sql.query<{ n: string }>(`SELECT indexname AS n FROM pg_indexes WHERE tablename = 'CyrusCatalogEntry'`)).map((r) => r.n));
    const col = (await sql.query(`SELECT 1 FROM information_schema.columns WHERE table_name = 'CyrusCatalogEntry' AND column_name = 'entryHash'`)).length > 0;
