  if (v && !v.ok) process.exit(4);
}

type Counts = { entries: number; terms: number; entriesWithoutTerms: number; byKind: Record<string, number>; byTier: Record<string, number>; byStatus: Record<string, number> };
async function counts(sql: ReturnType<typeof prismaSql>): Promise<Counts> {
  const n = (v: unknown) => Number(v ?? 0);
  const one1 = async (q: string) => n((await sql.query<{ n: unknown }>(q))[0]?.n);
  const grp = async (col: string) => Object.fromEntries((await sql.query<{ k: string; n: unknown }>(`SELECT "${col}" AS k, COUNT(*) AS n FROM "CyrusCatalogEntry" GROUP BY 1 ORDER BY 2 DESC`)).map((r) => [r.k, n(r.n)]));
  return {
