    terms: await one1(`SELECT COUNT(*) AS n FROM "CyrusCatalogTerm"`),
    entriesWithoutTerms: await one1(`SELECT COUNT(*) AS n FROM "CyrusCatalogEntry" e WHERE NOT EXISTS (SELECT 1 FROM "CyrusCatalogTerm" t WHERE t."entryId" = e.id)`),
    byKind: await grp("kind"), byTier: await grp("tier"), byStatus: await grp("status"),
  };
}
main().catch((e) => { console.error(e); process.exit(1); });
