// Validate a catalogue import THROUGH THE REAL APP CODE PATHS (library search, browse facets, signed-URL + file
// handlers, derivatives, licence/plan gates, admin read model) against a node-2 THROWAWAY database. It writes
// derivative rows/objects, so it refuses anything but a 127.0.0.1:5433/wt_* database.
//   DATABASE_URL=... CYRUS_LIBRARY_STAGING_DIR=/tank/cyrus-library-staging npx tsx scripts/cyrus/library-validate.ts \
//     --store /tmp/libstore [--per-kind 4] [--ffmpeg /usr/bin/ffmpeg] [--out report.json]
import { writeFileSync } from "node:fs";
import { PrismaClient } from "@prisma/client";
import { createPgCatalog, prismaSql } from "../../lib/cyrus/library/backend/pg";
import { LibraryStore } from "../../lib/cyrus/library/backend/library-store";
import { LocalObjectStore, StagingSource } from "../../lib/cyrus/library/backend/objects";
import { spawnTool, recipesFor } from "../../lib/cyrus/library/backend/derive";
import { libraryFlags } from "../../lib/cyrus/library/backend/flags";
import { handleFile, handleSignUrl, type LibraryHttpDeps } from "../../lib/cyrus/library/backend/http";
import { libraryAdminView } from "../../lib/cyrus/library/backend/admin";
import { browseCatalog } from "../../lib/cyrus/library/v2/browse";
import { catalogSearch } from "../../lib/cyrus/library/v2/tools";
import type { CatalogEntry } from "../../lib/cyrus/library/v2/entry";

const arg = (k: string, d?: string) => { const i = process.argv.indexOf(k); return i > 0 ? process.argv[i + 1] : d; };
if (!/@127\.0\.0\.1:5433\/wt_[a-z0-9_]+/.test(process.env.DATABASE_URL ?? "")) { console.error("refusing: not a node-2 throwaway database"); process.exit(3); }
const storeDir = arg("--store")!, perKind = Number(arg("--per-kind", "4"));
if (!storeDir?.startsWith("/")) { console.error("--store <absolute dir> required"); process.exit(2); }

const MAGIC: Record<string, (b: Buffer) => boolean> = {
  "image/png": (b) => b.subarray(1, 4).toString() === "PNG", "audio/ogg": (b) => b.subarray(0, 4).toString() === "OggS",
  "application/zip": (b) => b.subarray(0, 2).toString() === "PK", "model/gltf-binary": (b) => b.subarray(0, 4).toString() === "glTF",
};

async function main() {
  const prisma = new PrismaClient();
  const pg = createPgCatalog(prismaSql(prisma), { fuzzy: true });
  const flagsOf = (cleared: boolean) => libraryFlags({
    CYRUS_LIBRARY_BACKEND: "1", CYRUS_LIBRARY_STORE: "local", CYRUS_LIBRARY_LOCAL_DIR: storeDir, CYRUS_LIBRARY_STAGING_DIR: process.env.CYRUS_LIBRARY_STAGING_DIR,
    CYRUS_LIBRARY_URL_SECRET: "validate-secret-validate-secret-validate-secret", CYRUS_SOUND_LIBRARY_CLEARED: cleared ? "1" : "0",
    CYRUS_LIBRARY_FFMPEG: arg("--ffmpeg", "/usr/bin/ffmpeg"), CYRUS_LIBRARY_PYTHON: "/usr/bin/python3",
  });
  const store = new LibraryStore({ objects: new LocalObjectStore(storeDir), staging: new StagingSource(process.env.CYRUS_LIBRARY_STAGING_DIR!), records: pg.records, tools: { ...flagsOf(true).tools, run: spawnTool } });
  const depsFor = (plan: string | null, cleared: boolean): LibraryHttpDeps => ({
    flags: flagsOf(cleared), viewer: async () => ({ userId: "u-validate" }), planOf: async () => plan, rateLimit: () => ({ ok: true }),
    backend: () => ({ index: pg.index, catalog: pg.store, store, records: pg.records }),
  });
  const out: Record<string, unknown> = { at: new Date().toISOString(), perKind };

  // A. search (the model's tool + the browser), per plan
  const search: unknown[] = [];
  for (const [plan, q] of [["all", "wooden door"], ["all", "sci-fi crate prop"], ["all", "stone wall floor texture"], ["saka", "explosion sound"], ["saka", "wooden door"], ["free", "explosion sound"]] as const) {
    const t = Date.now();
    const r = await catalogSearch({ query: q, limit: 5 }, { index: pg.index, plan, game: "minecraft", proprietaryCleared: true });
    const b = JSON.parse(r.content) as { n?: number; rows?: { t: string; k: string }[]; error?: string };
    search.push({ plan, q, ms: Date.now() - t, n: b.n ?? 0, kinds: [...new Set((b.rows ?? []).map((x) => x.k))], top: b.rows?.[0]?.t, error: b.error });
  }
  out.search = search;
  const browse: unknown[] = [];
  for (const plan of ["all", "saka", "katara"]) for (const cleared of [true, false]) {
    const r = await browseCatalog({ text: "door", game: "minecraft" }, { index: pg.index, plan, proprietaryCleared: cleared });
    browse.push({ plan, cleared, total: r.total, rows: r.rows.length, kinds: r.kinds.length, tiers: r.tiers, locked: r.locked.map((l) => l.kind), notice: r.notice });
  }
  out.browse = browse;

  // C. pick entries per kind (deterministic), then sign + fetch every applicable variant
  const rows = await prisma.$queryRawUnsafe<{ id: string; kind: string; tier: string; status: string; entry: CatalogEntry }[]>(
    `SELECT id, kind, tier, status, entry FROM "CyrusCatalogEntry" WHERE status = 'published' ORDER BY md5(id)`);
  const picked = new Map<string, typeof rows>();
  for (const r of rows) { const k = `${r.kind}/${r.tier}`; const a = picked.get(k) ?? []; if (a.length < perKind) { a.push(r); picked.set(k, a); } }
  const served: Record<string, { tried: number; ok: number; fail: Record<string, number>; sampleMs: number[] }> = {};
  const deps = depsFor("all", true);
  const hit = async (id: string, variant: string, d = deps) => {
    const s = await handleSignUrl(new Request("http://x/u", { method: "POST", body: JSON.stringify({ id, variant }) }), d);
    if (s.status !== 200) return { status: s.status, code: ((await s.json()) as { code?: string }).code ?? "sign" };
    const { url } = (await s.json()) as { url: string };
    const t = Date.now();
    const f = await handleFile(new Request("http://x" + url), { token: url.split("/").pop()! }, d);
    if (f.status !== 200) return { status: f.status, code: ((await f.json()) as { code?: string }).code ?? "file" };
    const buf = Buffer.from(await f.arrayBuffer());
    const mime = f.headers.get("content-type") ?? "";
    return { status: 200, code: MAGIC[mime] && !MAGIC[mime](buf) ? "bad_magic" : "ok", bytes: buf.length, ms: Date.now() - t };
  };
  for (const [k, list] of picked) for (const r of list) {
    const variants = ["original", ...recipesFor(r.entry)] as const;
    for (const v of variants) {
      const key = `${k}:${v}`; const s = (served[key] ??= { tried: 0, ok: 0, fail: {}, sampleMs: [] });
      s.tried++;
      const h = await hit(r.id, v);
      if (h.code === "ok") { s.ok++; if (h.ms != null) s.sampleMs.push(h.ms); } else { const c = `${h.status}:${h.code}`; s.fail[c] = (s.fail[c] ?? 0) + 1; }
    }
  }
  out.served = served;

  // D. gates on known cases
  const one = async (where: string) => (await prisma.$queryRawUnsafe<{ id: string; entry: CatalogEntry }[]>(`SELECT id, entry FROM "CyrusCatalogEntry" WHERE ${where} ORDER BY md5(id) LIMIT 1`))[0];
  const prop = await one(`tier = 'proprietary-nxeon' AND status = 'published' AND kind = 'sound'`);
  const sound = await one(`tier = 'cc0' AND status = 'published' AND kind = 'sound'`);
  const model = await one(`tier = 'cc0' AND status = 'published' AND kind = 'sprite'`);
  const removed = await one(`status = 'removed' AND kind = 'sound'`) ?? await one(`status = 'removed'`);
  const held = await one(`status = 'held'`);
  const gates: Record<string, unknown> = {};
  const g = async (name: string, id: string | undefined, variant: string, d: LibraryHttpDeps) => { gates[name] = id ? await hit(id, variant, d) : "no sample"; };
  await g("proprietary preview, cleared, plan all", prop?.id, "preview-ogg@1", depsFor("all", true));
  await g("proprietary preview, NOT cleared", prop?.id, "preview-ogg@1", depsFor("all", false));
  await g("proprietary original (never)", prop?.id, "original", depsFor("all", true));
  await g("cc0 sound raw original (never)", sound?.id, "original", depsFor("all", true));
  await g("cc0 sound preview, saka", sound?.id, "preview-ogg@1", depsFor("saka", true));
  await g("cc0 sound preview, katara", sound?.id, "preview-ogg@1", depsFor("katara", true));
  await g("cc0 sound preview, unknown plan", sound?.id, "preview-ogg@1", depsFor(null, true));
  await g("visual thumb, saka (locked)", model?.id, "thumb@1", depsFor("saka", true));
  await g("removed entry", removed?.id, "thumb@1", depsFor("all", true));
  await g("held entry", held?.id, "thumb@1", depsFor("all", true));
  out.gates = gates;

  // E. admin read model
  out.admin = await libraryAdminView({
    counts: () => pg.admin.counts(), held: (n) => pg.store.listByStatus("held", null, n), openReports: (n) => pg.records.reports.open(undefined, n),
    log: (n) => pg.records.log.list({ limit: n }), derivativeStats: () => pg.admin.derivativeStats(), usesOfRemoved: () => pg.admin.usesOfRemoved(),
  }, { limit: 5 });
  out.adminFind = (await pg.admin.find("wooden door")).length;
  await prisma.$disconnect();
  const text = JSON.stringify(out, (_k, v) => (typeof v === "bigint" ? Number(v) : v), 1);
  console.log(text);
  if (arg("--out")) writeFileSync(arg("--out")!, text);
}
main().catch((e) => { console.error(e); process.exit(1); });
